IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[AppUser]') AND type = 'U') BEGIN CREATE TABLE [dbo].[AppUser] ( [Id] VARCHAR(100) NOT NULL, [UserName] VARCHAR(200) NOT NULL, [PasswordHash] VARCHAR(500) NOT NULL, [CreatedDateTime] DATETIME2(7) DEFAULT GETUTCDATE(), [UpdatedDateTime] DATETIME2(7) DEFAULT GETUTCDATE(), CONSTRAINT [PK_AppUser] PRIMARY KEY ([Id]), CONSTRAINT [UQ_AppUser_UserName_key] UNIQUE ([UserName]) ); END
EXEC(' IF NOT EXISTS (SELECT 1 FROM [dbo].[AppUser] WHERE [UserName] = ''john_doe'') INSERT INTO [dbo].[AppUser] ([Id],[UserName],[PasswordHash],[CreatedDateTime],[UpdatedDateTime]) VALUES (CONVERT(VARCHAR(100),NEWID()),''john_doe'',''hashed_password_123'',GETUTCDATE(),GETUTCDATE());
IF NOT EXISTS (SELECT 1 FROM [dbo].[AppUser] WHERE [UserName] = ''jane_smith'') INSERT INTO [dbo].[AppUser] ([Id],[UserName],[PasswordHash],[CreatedDateTime],[UpdatedDateTime]) VALUES (CONVERT(VARCHAR(100),NEWID()),''jane_smith'',''hashed_password_456'',GETUTCDATE(),GETUTCDATE()); ')

IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[User]') AND type = 'U') BEGIN CREATE TABLE [dbo].[User] ( [Id] VARCHAR(100) NOT NULL DEFAULT CONVERT(VARCHAR(100), NEWID()), [UserName] VARCHAR(200) NOT NULL, [EmpId] VARCHAR(6) NULL, [EmpType] VARCHAR(200) NULL, [FirstName] VARCHAR(200) NOT NULL, [LastName] VARCHAR(200) NOT NULL, [Email] VARCHAR(200) NULL, [SecondaryEmail] VARCHAR(200) NULL, [PhoneNumber] VARCHAR(20) NULL, [Extension] VARCHAR(20) NULL, [mobile] VARCHAR(20) NULL, [oid] VARCHAR(100) NULL, [preferred_username] VARCHAR(200) NULL, [display_name] VARCHAR(200) NULL, [given_name] VARCHAR(200) NULL, [family_name] VARCHAR(200) NULL, [Position] VARCHAR(200) NULL, [BusinessUnit] VARCHAR(200) NULL, [ManagerId] VARCHAR(100) NULL, [Designation] VARCHAR(200) NULL, [Department] VARCHAR(200) NULL, [Location] VARCHAR(200) NULL, [Organization] VARCHAR(200) NULL, [CreatedBy] VARCHAR(100) NULL, [CreatedDateTime] DATETIME DEFAULT GETUTCDATE(), [UpdatedBy] VARCHAR(100) NULL, [UpdatedDateTime] DATETIME DEFAULT GETUTCDATE(), [UpdateReason] VARCHAR(100) NULL, [IsDeleted] BIT NULL DEFAULT 0, [IsActive] BIT NULL DEFAULT 0, [OwnerId] VARCHAR(100) NULL, [IsApproved] BIT NULL DEFAULT 0, [ApproverId] VARCHAR(100) NULL, [ApprovedDateTime] DATETIME NULL, [IsAuthorized] BIT NULL DEFAULT 0, [AuthorizedById] VARCHAR(100) NULL, [AuthorizedDateTime] DATETIME NULL, [TenantId] VARCHAR(100) NULL, [SubTenantId] VARCHAR(100) NULL, [SysData] NVARCHAR(MAX) NULL, [AccessLevel] VARCHAR(50) NULL, [CorrelationId] VARCHAR(50) NULL, [AuditableRequestId] VARCHAR(50) NULL, [AuditableRequestName] VARCHAR(100) NULL, [AuditableSourceEventName] VARCHAR(100) NULL, [auth_type] VARCHAR(200) NULL, CONSTRAINT [PK_User] PRIMARY KEY ([Id]), CONSTRAINT [UQ_User_Email] UNIQUE ([Email]), CONSTRAINT [UQ_User_UserName] UNIQUE ([UserName]), CONSTRAINT [FK_User_AccessLevel] FOREIGN KEY ([AccessLevel]) REFERENCES [dbo].[UserAccessLevel]([AccessLevel]) ); END
EXEC(' IF NOT EXISTS (SELECT 1 FROM [dbo].[User] WHERE [UserName] = ''test_Admin_User@systemdesign.com'') INSERT INTO [dbo].[User] ( [UserName],[FirstName],[LastName],[Email],[SecondaryEmail],[PhoneNumber], [oid],[preferred_username],[display_name],[given_name],[family_name], [IsDeleted],[IsAuthorized],[IsActive],[CreatedBy],[CreatedDateTime],[UpdatedDateTime],[SysData],[AccessLevel] ) VALUES ( ''test_Admin_User@systemdesign.com'',''Test Admin'',''User'', ''test_Admin_User@systemdesign.com'',''test_Admin_User@systemdesign.com'',''77889988'', ''test_Admin_User@systemdesign.com'',''test_Admin_User@systemdesign.com'',''Test AdminUser'',''Test Admin'',''User'', 0,1,1,''test_Admin_User@systemdesign.com'',GETUTCDATE(),GETUTCDATE(),''db'',''L1'' );
IF NOT EXISTS (SELECT 1 FROM [dbo].[User] WHERE [UserName] = ''test_Level_1_User@systemdesign.com'') INSERT INTO [dbo].[User] ( [UserName],[FirstName],[LastName],[Email],[SecondaryEmail],[PhoneNumber], [oid],[preferred_username],[display_name],[given_name],[family_name], [IsDeleted],[IsAuthorized],[IsActive],[CreatedBy],[CreatedDateTime],[UpdatedDateTime],[SysData],[AccessLevel] ) VALUES ( ''test_Level_1_User@systemdesign.com'',''Test Level 1'',''User'', ''test_Level_1_User@systemdesign.com'',''test_Level_1_User@systemdesign.com'',''1212121212'', ''test_Level_1_User@systemdesign.com'',''test_Level_1_User@systemdesign.com'',''Test Level 1User'',''Test Level 1'',''User'', 0,1,1,''test_Level_1_User@systemdesign.com'',GETUTCDATE(),GETUTCDATE(),''db'',''L1'' );
IF NOT EXISTS (SELECT 1 FROM [dbo].[User] WHERE [UserName] = ''test_Level_2_User@systemdesign.com'') INSERT INTO [dbo].[User] ( [UserName],[FirstName],[LastName],[Email],[SecondaryEmail],[PhoneNumber], [oid],[preferred_username],[display_name],[given_name],[family_name], [IsDeleted],[IsAuthorized],[IsActive],[CreatedBy],[CreatedDateTime],[UpdatedDateTime],[SysData],[AccessLevel] ) VALUES ( ''test_Level_2_User@systemdesign.com'',''Test Level 2'',''User'', ''test_Level_2_User@systemdesign.com'',''test_Level_2_User@systemdesign.com'',''12121212121'', ''test_Level_2_User@systemdesign.com'',''test_Level_2_User@systemdesign.com'',''Test Level 2User'',''Test Level 2'',''User'', 0,1,1,''test_Level_2_User@systemdesign.com'',GETUTCDATE(),GETUTCDATE(),''db'',''L1'' ); ')
